esbmc_test_source:
contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We take a callee and calldata; the test checks that calling c.forward cannot increase
    // address(this).balance as observed after the external call (no net transfer from C to this contract).
    function run(address callee, bytes calldata data) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(true);

        // Record balances before attempting the forward call.
        uint256 beforeTestBal = address(this).balance;
        uint256 beforeCBal = address(c).balance;

        bool reverted;
        c.forward(callee, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterTestBal = address(this).balance;
        uint256 afterCBal = address(c).balance;

        // General rule: regardless of whether forward reverted or returned, the test contract's balance
        // must not be greater than it was before the call due to funds coming from c (i.e., no net gain).
        // We express this as: afterTestBal <= beforeTestBal + beforeCBal. However, we cannot assume any
        // specific transfer semantics except that C cannot increase the test contract's balance by sending
        // out more than C had before. A stronger and provable property for this C is: afterTestBal <= beforeTestBal + beforeCBal
        // but to avoid relying on subtraction in ways that underflow, we rewrite as:
        // afterTestBal - beforeTestBal <= beforeCBal  (safe because afterTestBal >= beforeTestBal may be false)
        // To keep the assert as a direct relation without subtraction that could underflow in Solidity's checked arithmetic,
        // we restate as: afterTestBal <= beforeTestBal + beforeCBal.
        assert(afterTestBal <= beforeTestBal + beforeCBal);
    }

    receive() external payable { }
}

